"use client";

import { OpenChat, useChat } from "@/context/ChatContext";
import ChatWindow from "./ChatWindow";
import { useAuthStore } from "@/store/useAuthStore";
import { X } from "lucide-react";

export function ChatOverlay() {
  const { openChats, closeChat, toggleChat } = useChat();
  const { user } = useAuthStore();

  const getDisplayName = (chat: OpenChat) => {
     // Safety check
     if (!user) return chat.user_name || chat.buyer_name || `Usuario #${chat.user_id}`;

     const myId = String(user.id);
     const supplierId = String(chat.supplier_id);
     const supplierUserId =
       chat.supplier_user_id !== undefined && chat.supplier_user_id !== null
         ? String(chat.supplier_user_id)
         : "";
     const buyerId = String(chat.user_id || chat.buyer_id);
     const effectiveMyRole: "supplier" | "client" | undefined =
       chat.my_role === "supplier" || chat.my_role === "client"
         ? chat.my_role
         : supplierUserId === myId
           ? "supplier"
           : supplierId === myId
             ? "supplier"
             : buyerId === myId
               ? "client"
               : undefined;

     // Construct my name for comparison
      const myName = (user.name || '').trim();

     // 1. Am I the Supplier? (Or Admin acting as Supplier)
     // If my ID matches supplier_user_id (or supplier_id for legacy), I MUST see the Client's Name.
     if (
       effectiveMyRole === "supplier" ||
       supplierUserId === myId ||
       (!effectiveMyRole && (user.role === 'supplier' || user.role === 'admin'))
     ) {
         // Check structured user object first
         if (chat.user) {
             const chatUserId = String(chat.user.id);
             // CRITICAL: Only use chat.user if it is NOT me.
             if (chatUserId !== myId) {
                 const name = chat.user.name || `${chat.user.first_name || ''} ${chat.user.last_name || ''}`.trim();
                 if (name && name.toLowerCase() !== myName.toLowerCase()) return name;
             }
         }
         
         // Fallback to flat fields
         // PRIORITIZE buyer_name, as that is explicitly the client.
         if (chat.buyer_name && chat.buyer_name.trim().toLowerCase() !== myName.toLowerCase()) {
             return chat.buyer_name;
         }

         // Use user_name if different from me
         if (chat.user_name && chat.user_name.trim().toLowerCase() !== myName.toLowerCase()) {
             return chat.user_name;
         }
         
         // IGNORE supplier_name completely for suppliers.
         // CHECK other_party_name carefully.
         if (chat.other_party_name) {
             const opName = chat.other_party_name.trim().toLowerCase();
             // If other_party_name is NOT me, and NOT the supplier name (which is likely me)
             const sName = (chat.supplier_name || '').trim().toLowerCase();
             
             if (opName !== myName.toLowerCase() && opName !== sName) {
                 return chat.other_party_name;
             }
         }
         
         // Absolute last resort
         return `Cliente #${buyerId}`;
     }

     // 2. Am I the Client?
     if (effectiveMyRole === "client" || myId === buyerId || user.role === 'client') {
         return chat.supplier_name || chat.other_party_name || `Proveedor #${supplierId}`;
     }

     // 3. Fallback
     return chat.user_name || chat.buyer_name || `Usuario #${chat.user_id}`;
   };

  if (openChats.length === 0) return null;

  return (
    <div className="fixed bottom-0 right-0 md:right-4 left-0 md:left-auto flex flex-col md:flex-row items-end gap-2 md:gap-4 z-[9999] pointer-events-none p-2 md:p-0">
      {openChats.map((chat, index) => (
        <div 
            key={chat.id} 
            className={`pointer-events-auto bg-white border border-gray-200 rounded-t-xl shadow-2xl overflow-hidden transition-all duration-300 ease-in-out flex flex-col
                ${chat.isMinimized ? 'w-full md:w-[200px] h-[48px]' : 'w-full md:w-[340px] h-[500px] md:h-[480px] max-h-[80vh]'}
                ${index === openChats.length - 1 ? 'flex' : 'hidden md:flex'}
            `}
        >
             {chat.isMinimized ? (
                 <div 
                    className="flex items-center justify-between p-3 bg-white hover:bg-gray-50 cursor-pointer h-full border-t-4 border-t-primary"
                    onClick={() => toggleChat(chat.id)}
                 >
                    <div className="flex items-center gap-2 overflow-hidden">
                        <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center text-[10px] font-bold shrink-0">
                            {getDisplayName(chat).charAt(0)}
                        </div>
                        <span className="font-semibold text-sm truncate">
                            {getDisplayName(chat)}
                        </span>
                    </div>
                    <button 
                        onClick={(e) => { e.stopPropagation(); closeChat(chat.id); }}
                        className="p-1 hover:bg-gray-200 rounded-full text-gray-500"
                    >
                        <X size={14} />
                    </button>
                 </div>
             ) : (
                 <ChatWindow 
                    initialConversation={chat}
                    productId={chat.product_id || null}
                    supplierId={chat.supplier_id}
                    supplierName={chat.supplier_name || chat.other_party_name}
                    supplierSlug={chat.supplier_slug}
                    isOwner={
                        chat.my_role === "supplier" ||
                        (chat.supplier_user_id !== undefined && chat.supplier_user_id !== null && String(chat.supplier_user_id) === String(user?.id)) ||
                        String(user?.id) === String(chat.supplier_id)
                    }
                    productData={{
                        title: chat.product_id
                          ? chat.product_title || "Producto"
                          : "",
                        // Backend contract: conversation.product_price ya viene calculado
                        price: typeof chat.product_price === "number" 
                          ? chat.product_price 
                          : Number(chat.product_price) || 0,
                        image: chat.product_id ? chat.product_image || "" : "",
                        slug: chat.product_id ? chat.product_slug : undefined
                    }}
                    supplierTransferData={chat.supplier_transfer_data || {
                        transfer_accepted: true 
                    }}
                    isOpen={true} 
                    onClose={() => closeChat(chat.id)}
                    onMinimize={() => toggleChat(chat.id)}
                    mode="docked"
                 />
             )}
        </div>
      ))}
    </div>
  );
}
